import{_ as t,o as d,c as o,a2 as a}from"./chunks/framework.CZqXuAiL.js";const u=JSON.parse('{"title":"Configuration Reference","description":"Every Firewall-Plus configuration value — node config.json, FWP_* environment variables, and panel admin settings.","frontmatter":{"title":"Configuration Reference","description":"Every Firewall-Plus configuration value — node config.json, FWP_* environment variables, and panel admin settings."},"headers":[],"relativePath":"firewall-plus/configuration/reference.md","filePath":"firewall-plus/configuration/reference.md","lastUpdated":null}'),s={name:"firewall-plus/configuration/reference.md"};function i(n,e,r,l,c,h){return d(),o("div",null,[...e[0]||(e[0]=[a(`<h1 id="configuration-reference" tabindex="-1">Configuration Reference <a class="header-anchor" href="#configuration-reference" aria-label="Permalink to &quot;Configuration Reference&quot;">​</a></h1><p>Firewall-Plus is configured in three places:</p><ul><li><strong>Node <code>config.json</code></strong> — <code>/etc/firewall-plus/config.json</code> on each Wings host</li><li><strong>Node environment variables</strong> — <code>FWP_*</code>, set in the systemd unit</li><li><strong>Panel admin settings</strong> — <strong>Admin → Firewall → Settings</strong> (stored in the panel database)</li></ul><hr><h2 id="node-config-json" tabindex="-1">Node <code>config.json</code> <a class="header-anchor" href="#node-config-json" aria-label="Permalink to &quot;Node \`config.json\`&quot;">​</a></h2><p>Path: <code>/etc/firewall-plus/config.json</code> (override with <code>FWP_CONFIG</code>). Validated with a strict schema at startup — the service refuses to boot on invalid values.</p><table tabindex="0"><thead><tr><th>Key</th><th>Type</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>panelUrl</code></td><td>string (URL)</td><td>—</td><td>URL of your Pterodactyl panel. Informational/identification use by the daemon.</td></tr><tr><td><code>apiEndpoint</code></td><td>string</td><td>—</td><td><strong>Legacy alias</strong> for <code>panelUrl</code>. Use <code>panelUrl</code> going forward.</td></tr><tr><td><code>listenAddress</code></td><td>string</td><td><code>127.0.0.1</code></td><td>Bind address. Keep loopback or an internal interface in production — never <code>0.0.0.0</code> without a populated <code>allowedIps</code>.</td></tr><tr><td><code>listenPort</code></td><td>int 1024–65535</td><td><code>8472</code></td><td>Bind port for the REST API.</td></tr><tr><td><code>allowedIps</code></td><td>string[]</td><td><code>[]</code></td><td>IP/CIDR whitelist (IPv4 and IPv6) allowed to call protected routes. Your panel&#39;s egress IP must be in here when binding beyond loopback.</td></tr><tr><td><code>trustProxy</code></td><td>bool</td><td><code>false</code></td><td>Set <code>true</code> <strong>only</strong> behind a trusted reverse proxy (nginx/caddy). When <code>false</code>, the direct peer IP is used, so the whitelist can&#39;t be bypassed with a spoofed <code>X-Forwarded-For</code>.</td></tr><tr><td><code>allowEmptyWhitelist</code></td><td>bool</td><td><code>false</code></td><td>Escape hatch for a non-loopback bind with an empty <code>allowedIps</code>. Without it, that combination <strong>refuses to start</strong> — any reachable host could otherwise drive iptables.</td></tr><tr><td><code>logLevel</code></td><td><code>debug</code>/<code>info</code>/<code>warn</code>/<code>error</code></td><td><code>info</code></td><td>Log verbosity (journald via systemd).</td></tr><tr><td><code>version</code></td><td>string</td><td><code>1.0.0</code></td><td>Reported in health <code>meta.version</code>. Managed by the installer — don&#39;t hand-edit.</td></tr><tr><td><code>geoipDbPath</code></td><td>string</td><td>—</td><td>Path to a MaxMind GeoLite2 Country/City <code>.mmdb</code>. When set and the file exists, the node reports GeoIP available and <code>geo_filter</code> rules become usable. The DB is licensed and not shipped — download it yourself per MaxMind&#39;s terms.</td></tr></tbody></table><p>Example:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;panelUrl&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;https://panel.example.com&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;listenAddress&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;127.0.0.1&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;listenPort&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">8472</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;allowedIps&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;10.0.0.5/32&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">],</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;trustProxy&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;logLevel&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;info&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;geoipDbPath&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;/etc/firewall-plus/GeoLite2-Country.mmdb&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>The bearer token is <strong>not</strong> in this file — it lives at <code>/etc/firewall-plus/token</code> (64 hex chars, chmod <code>600</code>; path overridable with <code>FWP_TOKEN</code>).</p><div class="info custom-block"><p class="custom-block-title">TLS</p><p>The daemon is intentionally <strong>HTTP-only</strong>. If you need encryption between panel and node, terminate TLS at a reverse proxy on the node and set <code>trustProxy: true</code>. Do not point the panel at <code>https://</code> port 8472 directly — that&#39;s the &quot;OpenSSL wrong version number&quot; failure.</p></div><hr><h2 id="node-environment-variables" tabindex="-1">Node Environment Variables <a class="header-anchor" href="#node-environment-variables" aria-label="Permalink to &quot;Node Environment Variables&quot;">​</a></h2><p>Set in <code>/etc/systemd/system/firewall-plus.service</code> (<code>Environment=</code> lines), then <code>systemctl daemon-reload &amp;&amp; systemctl restart firewall-plus</code>.</p><table tabindex="0"><thead><tr><th>Variable</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>FWP_CONFIG</code></td><td><code>/etc/firewall-plus/config.json</code></td><td>Config file path.</td></tr><tr><td><code>FWP_TOKEN</code></td><td><code>/etc/firewall-plus/token</code></td><td>Bearer token file path. Must contain exactly 64 hex characters.</td></tr><tr><td><code>FWP_STATE_DIR</code></td><td><code>/var/lib/firewall-plus</code></td><td>State directory (server configs, snapshots, queue state).</td></tr><tr><td><code>FWP_LOG_LEVEL</code></td><td>from config</td><td>Overrides <code>logLevel</code>.</td></tr><tr><td><code>FWP_SKIP_IPTABLES</code></td><td>unset</td><td>Dev mode: when <code>1</code>, skips all snapshot/restore/iptables work — config is still written to disk and the queue flows normally. Used by the test scripts.</td></tr><tr><td><code>FWP_IPTABLES_BIN</code></td><td>auto-detect</td><td>Force the iptables binary, e.g. <code>/usr/sbin/iptables-nft</code>. The daemon auto-prefers the nft-backed binaries when present.</td></tr><tr><td><code>FWP_IPTABLES_SAVE_BIN</code></td><td>auto-detect</td><td>Force the save binary, e.g. <code>/usr/sbin/iptables-nft-save</code>.</td></tr><tr><td><code>FWP_IPTABLES_RESTORE_BIN</code></td><td>auto-detect</td><td>Force the restore binary, e.g. <code>/usr/sbin/iptables-nft-restore</code>.</td></tr><tr><td><code>FWP_IPTABLES_RESTORE_TIMEOUT_MS</code></td><td><code>120000</code></td><td>Max wait for a single <code>iptables-restore</code>, clamped to 10s–600s. Raise only to ride out netfilter contention (e.g. Docker on the same host) — it doesn&#39;t remove the contention.</td></tr><tr><td><code>FWP_IPSET_BIN</code></td><td>auto-detect</td><td>Force the ipset binary.</td></tr><tr><td><code>FWP_CHAIN_RE</code></td><td>built-in</td><td>Override the regex used to recognize Firewall-Plus chains (<code>FWP-*</code>). Drift checker and inspector. Almost never needed.</td></tr><tr><td><code>FWP_CONNTRACK_PATH</code></td><td>auto-detect</td><td>Path to conntrack data for SMART metrics. Only touch on exotic kernels.</td></tr><tr><td><code>FWP_METRICS_TICK_MS</code></td><td>built-in</td><td>Metrics collection tick interval. Lower = finer charts, more CPU.</td></tr><tr><td><code>FWP_TEST_TOKEN</code></td><td>—</td><td>Test scripts only: token used by <code>load-test-apply.mjs</code> / <code>test-queue.mjs</code>.</td></tr></tbody></table><hr><h2 id="panel-admin-settings" tabindex="-1">Panel Admin Settings <a class="header-anchor" href="#panel-admin-settings" aria-label="Permalink to &quot;Panel Admin Settings&quot;">​</a></h2><p><strong>Admin → Firewall → Settings.</strong> Stored in <code>firewall_admin_settings</code>; changes take effect immediately.</p><h3 id="limits" tabindex="-1">Limits <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Limits&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Setting</th><th>Description</th></tr></thead><tbody><tr><td><code>max_rules_per_server</code></td><td>Maximum firewall rules a single server may have. Enforced by the LimitChecker on create.</td></tr><tr><td><code>max_whitelist_entries</code></td><td>Maximum whitelist entries per server.</td></tr><tr><td><code>max_blacklist_entries</code></td><td>Maximum blacklist entries per server.</td></tr><tr><td><code>max_abusedb_saved_lookups</code></td><td>Maximum saved AbuseIPDB lookups retained per server.</td></tr></tbody></table><h3 id="nodes" tabindex="-1">Nodes <a class="header-anchor" href="#nodes" aria-label="Permalink to &quot;Nodes&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Setting</th><th>Description</th></tr></thead><tbody><tr><td><code>node_ping_interval_seconds</code></td><td>How often the panel health-checks each node.</td></tr><tr><td><code>node_offline_fail_threshold</code></td><td>Failed health checks before a node is marked OFFLINE (default <strong>2</strong>). When a node returns ONLINE, a reconcile is dispatched automatically.</td></tr><tr><td><code>node_offline_webhook_max</code></td><td>Maximum offline notifications sent per node incident — prevents webhook spam during flapping.</td></tr></tbody></table><h3 id="notifications-abuseipdb" tabindex="-1">Notifications &amp; AbuseIPDB <a class="header-anchor" href="#notifications-abuseipdb" aria-label="Permalink to &quot;Notifications &amp; AbuseIPDB&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Setting</th><th>Description</th></tr></thead><tbody><tr><td><code>webhook_url</code></td><td>Admin Discord webhook for firewall events (applies, node incidents, SMART attacks). See <a href="./../user-guide/webhooks">Webhooks &amp; Alerts</a>.</td></tr><tr><td><code>abusedb_enabled</code></td><td>Master switch for the AbuseIPDB client tab and API.</td></tr><tr><td><code>audit_retention_days</code></td><td>Days of audit history kept; pruned daily by <code>firewall-plus:prune-audit-logs</code> (default 90).</td></tr><tr><td><code>tos_text</code></td><td>Terms-of-Service text users must accept before any firewall mutation. Supports markdown.</td></tr><tr><td><code>log_level</code></td><td>Panel-side firewall log verbosity.</td></tr></tbody></table><h3 id="smart-detection" tabindex="-1">SMART detection <a class="header-anchor" href="#smart-detection" aria-label="Permalink to &quot;SMART detection&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Setting</th><th>Description</th></tr></thead><tbody><tr><td><code>smart_alpha</code></td><td>EWMA smoothing factor (0–1). Higher reacts faster, noisier.</td></tr><tr><td><code>smart_anomaly_multiplier</code></td><td>How many multiples over the EWMA baseline counts as an anomaly. Lower = more sensitive.</td></tr><tr><td><code>smart_warmup_samples</code></td><td>Samples collected before detection arms — avoids false positives on fresh servers.</td></tr><tr><td><code>smart_rate_limit</code></td><td>Rate cap applied by SMART mitigations.</td></tr><tr><td><code>smart_owner_email_enabled</code></td><td>When on, server <strong>owners receive email alerts</strong> for SMART attack events (panel mailable), in addition to their per-server Discord webhook. Off = Discord-only.</td></tr></tbody></table><h3 id="global-toggles" tabindex="-1">Global toggles <a class="header-anchor" href="#global-toggles" aria-label="Permalink to &quot;Global toggles&quot;">​</a></h3><p>The settings page also carries the <strong>global enable switch</strong> (master off switch for the whole addon) and the <strong>fleet access</strong> toggle; the <strong>Emergency</strong> page holds <code>emergency_mode</code> (blocks all user mutations) and per-rule-type fleet disables. See the runbook-style procedures on the <a href="./../user-guide/cli#emergency-operations">CLI page</a>.</p><div class="warning custom-block"><p class="custom-block-title">Common mistakes</p><ul><li>Changing <code>listenPort</code>/<code>listenAddress</code> on the node without updating the node&#39;s FQDN/port in <strong>Admin → Firewall → Nodes</strong> — health checks start failing silently.</li><li>Setting <code>trustProxy: true</code> without an actual proxy — the IP whitelist becomes spoofable.</li><li>Copying the Wings daemon URL scheme (HTTPS) onto the Firewall-Plus node FQDN — the daemon speaks plain HTTP.</li></ul></div>`,29)])])}const g=t(s,[["render",i]]);export{u as __pageData,g as default};
